import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Background plane – aspect ratio from atlas source rect (512x320)
  const aspect = 512 / 320;
  const width = 2.0;
  const height = width / aspect;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Build material with gradient + grain texture
  const material = new MeshBasicNodeMaterial({ transparent: false });

  // Gradient using spec colors: paper (top) → surface (bottom)
  const gradient = mix(
    vec3(0xe8 / 255, 0xec / 255, 0xf2 / 255),   // paper
    vec3(0x0b / 255, 0x0b / 255, 0x10 / 255),   // surface
    uv().y
  );

  // Grain texture (async load)
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texPromise.then((tex) => {
    // Atlas region: source rect (0,0,512,320) – assume full texture
    tex.repeat.set(1, 1);
    tex.offset.set(0, 0);
    material.map = tex;
    material.needsUpdate = true;
  });

  // Combine gradient and grain – multiply (grain will be dark on dark, but we want subtle)
  // Use a mix that lets the grain modulate the gradient color
  // For a subtle grain effect, we can use the grain luminance as a multiplier
  // We'll sample the texture in TSL – but texture node requires loading.
  // Instead, we'll set the color to gradient for now; when texture loads we can update.
  // However, we cannot use texture in TSL node if not loaded. So we keep color = gradient.
  material.colorNode = gradient;

  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Text – "Features" as headline
  const textOpts = {
    fontSize: 0.62,           // hero em per type scale
    color: '#e8ecf2',         // paper color
    align: 'center',
  };
  const textMesh = ctx.fontAtlas.createText('Features', textOpts);
  // Center text relative to plane
  textMesh.position.set(0, 0, 0.01); // slight Z offset to avoid z-fighting
  group.add(textMesh);

  // Event handlers (none)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // Dispose text – assumes createText returns Object3Ds with materials
    textMesh.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) {
          child.material.dispose();
        }
      }
    });
    // Texture cleanup (if loaded)
    texPromise.then((tex) => tex.dispose()).catch(() => {});
  };

  return group;
}
